import { browserManager } from '../browser.js';
import { CONFIG, log, logError } from '../config.js';
import fs from 'fs';
import path from 'path';
import https from 'https';

export type ImageSize = '1024x1024' | '1792x1024' | '1024x1792';

export interface GenerateImageOptions {
  prompt: string;
  outputPath: string;
  size?: ImageSize;
}

export interface GenerateImageResult {
  success: boolean;
  imagePath?: string;
  error?: string;
}

export async function generateImage(options: GenerateImageOptions): Promise<GenerateImageResult> {
  const { prompt, outputPath, size = '1024x1024' } = options;

  try {
    const page = await browserManager.getPage();

    // 1. Naviguer vers une nouvelle conversation
    await page.goto(`${CONFIG.chatgptUrl}/?model=gpt-4`, { waitUntil: 'networkidle' });

    // 2. Construire le prompt DALL-E
    const dallePrompt = `Generate an image: ${prompt}. Size: ${size}`;

    // 3. Entrer le prompt dans le textarea
    const textarea = await page.waitForSelector('#prompt-textarea', { timeout: 10000 });
    await textarea.fill(dallePrompt);

    // 4. Soumettre le prompt
    await page.keyboard.press('Enter');

    // 5. Attendre la génération d'image (jusqu'à 2 minutes)
    const imageSelector = 'img[alt*="DALL"], img[src*="oaidalleapi"], img.dalle-image';
    await page.waitForSelector(imageSelector, { timeout: CONFIG.imageGenerationTimeout });

    // 6. Extraire l'URL de l'image
    const imageUrl = await page.evaluate((sel) => {
      const img = document.querySelector(sel) as HTMLImageElement;
      return img?.src || null;
    }, imageSelector);

    if (!imageUrl) {
      return { success: false, error: 'Image URL not found in response' };
    }

    // 7. Télécharger et sauvegarder l'image
    await downloadImage(imageUrl, outputPath);

    return { success: true, imagePath: outputPath };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logError('Image generation failed:', message);
    return { success: false, error: message };
  }
}

