import express from 'express';
import cors from 'cors';
import { CONFIG, log, logError } from './config.js';
import { browserManager } from './browser.js';
import { generateImage } from './tools/generate-image.js';

const app = express();
app.use(cors());
app.use(express.json());

// Logging middleware
app.use((req, res, next) => {
  log(`${req.method} ${req.path}`);
  next();
});

// GET /health - État du serveur
app.get('/health', async (req, res) => {
  try {
    const loggedIn = await browserManager.ensureLoggedIn().catch(() => false);
    res.json({
      status: 'ok',
      loggedIn,
      browserReady: true
    });
  } catch (error) {
    res.json({
      status: 'ok',
      loggedIn: false,
      browserReady: false
    });
  }
});

// POST /generate-image - Générer une image
app.post('/generate-image', async (req, res) => {
  const { prompt, outputPath, size } = req.body;

  if (!prompt || !outputPath) {
    return res.status(400).json({ error: 'prompt and outputPath are required' });
  }

  const result = await generateImage({ prompt, outputPath, size });
  res.json(result);
});

// GET /login - Ouvrir le navigateur pour login manuel
app.get('/login', async (req, res) => {
  try {
    await browserManager.openLoginPage();
    res.json({ message: 'Login page opened. Please login manually.' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to open login page' });
  }
});

// Gestion du shutdown gracieux
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

async function shutdown() {
  log('Shutting down...');
  await browserManager.close();
  process.exit(0);
}

// Démarrage du serveur
async function start() {
  // Vérifier les arguments CLI
  if (process.argv.includes('--login')) {
    await browserManager.openLoginPage();
    return;
  }

  await browserManager.initialize();

  app.listen(CONFIG.port, CONFIG.host, () => {
    log(`Server running at http://${CONFIG.host}:${CONFIG.port}`);
  });
}

start().catch((error) => {
  logError('Failed to start server:', error);
  process.exit(1);
});
