interface RateLimitInfo {
  isLimited: boolean;
  retryAfter?: number;
  message?: string;
}

async function checkRateLimit(page: Page): Promise<RateLimitInfo> {
  // Vérifier les messages d'erreur de rate limit dans la page
  const rateLimitIndicators = [
    'text="You\'ve reached the limit"',
    'text="Please wait"',
    'text="Rate limit"',
    '.error-message'
  ];

  for (const selector of rateLimitIndicators) {
    const element = await page.$(selector);
    if (element) {
      const text = await element.textContent();
      return {
        isLimited: true,
        message: text || 'Rate limited',
        retryAfter: 60000 // 1 minute par défaut
      };
    }
  }

  return { isLimited: false };
}

// Dans generateImage():
const rateLimitCheck = await checkRateLimit(page);
if (rateLimitCheck.isLimited) {
  return {
    success: false,
    error: `Rate limited: ${rateLimitCheck.message}. Retry after ${rateLimitCheck.retryAfter}ms`
  };
}
