export async function findElement(page: Page, selectorList: string[]): Promise<ElementHandle | null> {
  for (const selector of selectorList) {
    const element = await page.$(selector).catch(() => null);
    if (element) return element;
  }
  return null;
}

export async function waitForAnySelector(page: Page, selectorList: string[], timeout: number): Promise<ElementHandle> {
  const selectorString = selectorList.join(', ');
  return page.waitForSelector(selectorString, { timeout });
